import useSWR, { mutate } from 'swr'
export function useModal() {
const { data: isVisible, mutate: setVisible } = useSWR<boolean>(
'state:modal',
{
fallbackData: false,
},
)
return {
isVisible,
setVisible,
}
}
// For when you can't use hooks
export const mutateModal = (isVisible) => {
mutate('state:modal', isVisible)
}
